    def __init__(self, title, category):
        self.title = title
        self.category = category

    def __eq__(self, other):
        if not isinstance(other, Task):
            return NotImplemented
        return (self.title, self.category) == (other.title, other.category)

def snapshot_key(task):
    return (task.title, task.category)
first = Task("read", "study")
second = Task("read", "study")
a = snapshot_key(first)
b = snapshot_key(second)
print(first == second)
print(a == b, hash(a) == hash(b))
try:
    hash(first)
except TypeError:
    print("unhashable task")
```
It prints True; True True; unhashable task. Calling hash on the Task raises TypeError rather than returning a usable hash.

Reassigning a task field does not rewrite an earlier tuple of its string values.
```python
class Task:
    def __init__(self, title, category):
        self.title = title
        self.category = category

    def __eq__(self, other):
        if not isinstance(other, Task):
            return NotImplemented
        return (self.title, self.category) == (other.title, other.category)

def snapshot_key(task):
    return (task.title, task.category)
task = Task("read", "study")
old_key = snapshot_key(task)
task.title = "write"
print(old_key)
print(old_key == snapshot_key(task))
```
It prints ('read', 'study') and False. Build a new snapshot when you want a key for the new values; do not silently change a key already in a collection.

